function nthTerm(n: number): number {
  // returns [F(k), F(k + 1)]
  const pair = (k: number): [number, number] => {
    if (k === 0) return [0, 1];
    const [a, b] = pair(k >> 1);
    const c = a * (2 * b - a), d = a * a + b * b;
    return k & 1 ? [d, c + d] : [c, d];
  };
  return pair(n)[0];
}

